#include <stdint.h>

/* Bench-measured linear correction, gain then offset, both fixed-point
 * (values are the real number x1000) so the target never needs an FPU. */
#define AO_GAIN        990u    /* slope,  x1000 -> real gain   0.990        */
#define AO_OFFSET     3000u    /* offset, x1000 -> real offset 3 DAC counts */
#define AO_SCALE      1000u
#define AO_FULL_SCALE 4095u    /* 12-bit DAC, 0-10V full scale */

/**
 * @brief Apply the bench calibration to a raw analogue-output value and
 *        clamp it to the DAC's range.
 *
 * @param raw Pre-correction DAC value, 0..4095 (0 = sensor reading nothing).
 * @return Corrected DAC value, clamped to 0..4095.
 *
 * @note Bug report: with the output tracking measured motor current, it
 *       reads full-scale (~10V) while the motor is stopped, and only drops
 *       to a sensible, current-proportional value once the motor starts
 *       drawing current.
 */
uint16_t scale_analogue_output(uint16_t raw)
{
    uint32_t dw = raw;

    dw *= AO_GAIN;
    dw -= AO_OFFSET;
    dw /= AO_SCALE;

    if (dw > AO_FULL_SCALE)
    {
        dw = AO_FULL_SCALE;
    }

    return (uint16_t)dw;
}

