"""Random raw pre-correction DAC readings.

Weighted towards the low end of the range, where the underflow bug lives,
plus ordinary mid-range and near-full-scale readings so a fix has to stay
correct everywhere, not just at zero.
"""

FULL_SCALE = 4095


def generate(rng, count):
    builders = (_near_zero, _low_band, _mid_range, _near_full_scale)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, raws, description=""):
    body = "\n".join(str(r) for r in raws)
    return {"name": name, "stdin": body + "\n", "description": description}


def _near_zero(rng, index):
    raws = [0] + sorted(rng.randint(0, 3) for _ in range(4))
    return _case("a run of readings at or near zero #%d" % index, raws,
                 "The motor-stopped case and its close neighbours -- all "
                 "inside the band where the correction can underflow.")


def _low_band(rng, index):
    raws = list(range(0, 12))
    return _case("every reading from 0 up to 11 #%d" % index, raws,
                 "Walks straight across the underflow band and a few counts "
                 "past it, so the exact edge shows up in the output.")


def _mid_range(rng, index):
    raws = sorted(rng.sample(range(20, 3000), 6))
    return _case("ordinary mid-range current readings #%d" % index, raws,
                 "Comfortably clear of the underflow band -- correct on "
                 "both the buggy and the fixed code.")


def _near_full_scale(rng, index):
    raws = sorted(rng.sample(range(3800, FULL_SCALE + 1), 5))
    return _case("readings near full-scale current #%d" % index, raws,
                 "Close to the top of the input range -- checks the clamp "
                 "is still doing its real job, not just papering over the "
                 "underflow.")
